# Kaggle script kernel (CPU): quantile/nanquantile tie-gradient cases on torch nightly then 2.14.0 (self-contained).
import base64, subprocess, sys
open("diag_quantile_ties.py", "wb").write(base64.b64decode(""))
subprocess.run(["pip", "-q", "install", "--pre", "--upgrade", "torch", "--index-url", "https://download.pytorch.org/whl/nightly/cpu"])
subprocess.run([sys.executable, "diag_quantile_ties.py"])
subprocess.run(["pip", "-q", "install", "torch==2.14.0", "--index-url", "https://download.pytorch.org/whl/cpu"])
subprocess.run([sys.executable, "diag_quantile_ties.py"])
print("JOB DONE", flush=True)
